package com.growworld.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import java.nio.charset.StandardCharsets; import java.time.*; import java.util.*; import javax.crypto.SecretKey; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service;
@Service public class JwtService { private final SecretKey key; private final long hours; public JwtService(@Value("${app.jwt.secret}") String secret,@Value("${app.jwt.expiration-hours}") long hours){this.key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.hours=hours;} public String create(UUID id){var now=Date.from(Instant.now());return Jwts.builder().subject(id.toString()).issuedAt(now).expiration(Date.from(Instant.now().plus(Duration.ofHours(hours)))).signWith(key).compact();} public UUID subject(String token){return UUID.fromString(Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload().getSubject());} }
